### Python

```python
import sys
import random

# Treap 节点
class Node:
    def __init__(self, key, val):
        self.key = key          # 区间左端点
        self.val = val          # 区间右端点
        self.pri = random.randint(1, 1 << 30)  # 随机优先级
        self.left = None
        self.right = None

# 按 key 分裂，返回 (< key, >= key)
def split(root, key):
    if root is None:
        return None, None
    if root.key < key:
        a, b = split(root.right, key)
        root.right = a
        return root, b
    else:
        a, b = split(root.left, key)
        root.left = b
        return a, root

# 合并两棵 Treap，要求左边所有 key 都小于右边
def merge(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a.pri < b.pri:
        a.right = merge(a.right, b)
        return a
    else:
        b.left = merge(a, b.left)
        return b

# 插入一个新区间节点
def insert(root, node):
    if root is None:
        return node
    if node.pri < root.pri:
        a, b = split(root, node.key)
        node.left = a
        node.right = b
        return node
    if node.key < root.key:
        root.left = insert(root.left, node)
    else:
        root.right = insert(root.right, node)
    return root

# 查找 key <= x 的前驱节点
def find_prev(root, x):
    ans = None
    cur = root
    while cur is not None:
        if cur.key <= x:
            ans = cur
            cur = cur.right
        else:
            cur = cur.left
    return ans

# 删除并返回最小节点
def pop_min(root):
    if root.left is None:
        return root.right, root
    new_left, node = pop_min(root.left)
    root.left = new_left
    return root, node

# 删除并返回最大节点
def pop_max(root):
    if root.right is None:
        return root.left, root
    new_right, node = pop_max(root.right)
    root.right = new_right
    return root, node

# 查找最小节点
def get_min(root):
    cur = root
    while cur.left is not None:
        cur = cur.left
    return cur

# 处理所有操作
def solve_operations(ops):
    root = None
    ans = []

    for l, r, x in ops:
        # 先按 l 分裂，左边都是左端点 < l 的区间
        a, b = split(root, l)

        # 检查左边最后一个区间是否与 [l, r] 相交
        prev = find_prev(a, 10**30)
        if prev is not None and prev.val >= l:
            a, node = pop_max(a)
            l = min(l, node.key)
            r = max(r, node.val)

        # 把右边所有与 [l, r] 相交的区间不断合并进来
        while b is not None:
            first = get_min(b)
            if first.key > r:
                break
            b, node = pop_min(b)
            r = max(r, node.val)

        # 插入合并后的新区间
        root = merge(a, merge(Node(l, r), b))

        # 查询 x 所在连通组的最右端点
        node = find_prev(root, x)
        if node is not None and node.val >= x:
            ans.append(str(node.val))
        else:
            ans.append(str(x))

    return ans

def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    ops = []
    for _ in range(m):
        l, r, x = map(int, input().split())
        ops.append((l, r, x))

    res = solve_operations(ops)
    sys.stdout.write("\n".join(res))

if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Map;
import java.util.StringTokenizer;
import java.util.TreeMap;

public class Main {

    // 处理所有操作：区间合并与查询
    public static StringBuilder solveOperations(int[][] ops) {
        // key 为区间左端点，value 为区间右端点
        TreeMap<Integer, Integer> map = new TreeMap<>();
        StringBuilder sb = new StringBuilder();

        for (int[] op : ops) {
            int l = op[0];
            int r = op[1];
            int x = op[2];

            // 先看左边最后一个区间是否与 [l, r] 相交
            Map.Entry<Integer, Integer> entry = map.floorEntry(l);
            if (entry != null && entry.getValue() >= l) {
                l = Math.min(l, entry.getKey());
                r = Math.max(r, entry.getValue());
                map.remove(entry.getKey());
            }

            // 不断合并所有与 [l, r] 相交的后续区间
            entry = map.ceilingEntry(l);
            while (entry != null && entry.getKey() <= r) {
                r = Math.max(r, entry.getValue());
                map.remove(entry.getKey());
                entry = map.ceilingEntry(l);
            }

            // 插入合并后的新区间
            map.put(l, r);

            // 查询 x 所在连通组的最右端点
            entry = map.floorEntry(x);
            if (entry != null && entry.getValue() >= x) {
                sb.append(entry.getValue()).append('\n');
            } else {
                sb.append(x).append('\n');
            }
        }

        return sb;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int[][] ops = new int[m][3];
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            ops[i][0] = Integer.parseInt(st.nextToken());
            ops[i][1] = Integer.parseInt(st.nextToken());
            ops[i][2] = Integer.parseInt(st.nextToken());
        }

        StringBuilder ans = solveOperations(ops);
        System.out.print(ans);
    }
}
